mapper.select:
SELECT id, user_id, session_id, role, content, create_time
FROM (
    SELECT id, user_id, session_id, role, content, create_time
    FROM ai_chat_record
    WHERE user_id = #{userId}
    AND session_id = #{sessionId}
    ORDER BY create_time DESC
    LIMIT #{limit}
) recent
ORDER BY create_time ASC
